import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { CheckCircle, Lock, MapPin, Star, X } from 'lucide-react';
import AuthForm from '../components/AuthForm';
import { useNavigate } from 'react-router-dom';

const allProperties = [
  {
    id: 1,
    title: "Modern 2BHK in Bengaluru",
    location: "Whitefield, Bengaluru",
    price: 25000,
    deposit: 50000,
    type: "Flat",
    rating: 4.5,
    image: "data:image/jpeg;base64,",
    aiVerified: true,
    blockchainVerified: true,
  },
  {
    id: 2,
    title: "Cozy 1RK for Students",
    location: "Hinjewadi, Pune",
    price: 9000,
    deposit: 10000,
    type: "PG",
    rating: 4.0,
    image: "data:image/jpeg;base64,",
    aiVerified: true,
    blockchainVerified: false,
  },
  {
    id: 3,
    title: "Modern 2BHK in Bengaluru",
    location: "Whitefield, Bengaluru",
    price: 25000,
    deposit: 50000,
    type: "Flat",
    rating: 4.5,
    image: "data:image/jpeg;base64,",
    aiVerified: true,
    blockchainVerified: true,
  },
  {
    id: 4,
    title: "Modern 2BHK in Bengaluru",
    location: "Whitefield, Bengaluru",
    price: 25000,
    deposit: 50000,
    type: "Flat",
    rating: 4.5,
    image: "data:image/jpeg;base64,",
    aiVerified: true,
    blockchainVerified: true,
  },
  {
    id: 5,
    title: "Modern 2BHK in Bengaluru",
    location: "Whitefield, Bengaluru",
    price: 25000,
    deposit: 50000,
    type: "Flat",
    rating: 4.5,
    image: "data:image/jpeg;base64,",
    aiVerified: true,
    blockchainVerified: true,
  },
];

const Properties = () => {
  const [query, setQuery] = useState('');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const [filtered, setFiltered] = useState(allProperties);
  const [selectedProperty, setSelectedProperty] = useState(null);
  const token = localStorage.getItem('token');
  const navigate = useNavigate()

  const handleFilter = () => {
    let filteredList = allProperties.filter(p => {
      return (
        p.title.toLowerCase().includes(query.toLowerCase()) &&
        (!minPrice || p.price >= Number(minPrice)) &&
        (!maxPrice || p.price <= Number(maxPrice))
      );
    });
    setFiltered(filteredList);
  };

  const openModal = (property) => {
    setSelectedProperty(property);
  };

  const closeModal = () => {
    setSelectedProperty(null);
  };

  return token ? (
    <div className="pt-24 px-6 max-w-7xl mx-auto min-h-screen">
      <h1 className="text-4xl font-bold text-blue-800 mb-8">Smart Verified Properties</h1>

      {/* Filter Section */}
      <div className="bg-white shadow-lg p-6 rounded-2xl mb-8 grid md:grid-cols-4 gap-4">
        <input
          type="text"
          placeholder="Search by title or location"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="border border-gray-300 p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <input
          type="number"
          placeholder="Min Price"
          value={minPrice}
          onChange={(e) => setMinPrice(e.target.value)}
          className="border border-gray-300 p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <input
          type="number"
          placeholder="Max Price"
          value={maxPrice}
          onChange={(e) => setMaxPrice(e.target.value)}
          className="border border-gray-300 p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <button
          onClick={handleFilter}
          className="bg-blue-700 text-white rounded-lg px-6 py-3 hover:bg-blue-800 transition duration-300"
        >
          Apply Filters
        </button>
      </div>

      {/* Property Listings */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filtered.map((property, idx) => (
          <motion.div
            key={property.id}
            initial={{ opacity: 0, y: 40 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: idx * 0.1 }}
            className="bg-white rounded-2xl shadow-xl overflow-hidden cursor-pointer hover:shadow-2xl transition-shadow duration-300"
            onClick={() => openModal(property)}
          >
            <img
              src={property.image}
              alt={property.title}
              className="w-full h-56 object-cover"
            />
            <div className="p-6">
              <h2 className="text-2xl font-semibold text-blue-800">{property.title}</h2>
              <div className="flex items-center text-gray-600 text-sm mt-2">
                <MapPin size={16} className="mr-1" /> {property.location}
              </div>
              <div className="my-3 text-sm space-y-1">
                <p><strong>Rent:</strong> ₹{property.price}/month</p>
                <p><strong>Deposit:</strong> ₹{property.deposit}</p>
                <p><strong>Type:</strong> {property.type}</p>
              </div>
              <div className="flex items-center gap-3 mt-4 text-sm">
                {property.aiVerified && (
                  <span className="text-green-600 flex items-center gap-1">
                    <CheckCircle size={16} /> AI Verified
                  </span>
                )}
                {property.blockchainVerified ? (
                  <span className="text-blue-600 flex items-center gap-1">
                    <Lock size={16} /> Blockchain Verified
                  </span>
                ) : (
                  <span className="text-yellow-600 flex items-center gap-1">
                    <Lock size={16} /> Pending Verification
                  </span>
                )}
              </div>
              <div className="flex items-center text-yellow-500 mt-3">
                {Array.from({ length: 5 }, (_, i) => (
                  <Star
                    key={i}
                    size={16}
                    fill={i < Math.floor(property.rating) ? 'currentColor' : 'none'}
                  />
                ))}
                <span className="text-gray-500 text-xs ml-2">{property.rating} / 5</span>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Property Detail Modal */}
      <AnimatePresence>
        {selectedProperty && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50"
          >
            <motion.div
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.8, opacity: 0 }}
              className="bg-white rounded-3xl max-w-lg w-full mx-4 overflow-hidden shadow-2xl"
            >
              <div className="relative">
                <img
                  src={selectedProperty.image}
                  alt={selectedProperty.title}
                  className="w-full h-64 object-cover"
                />
                <button
                  onClick={closeModal}
                  className="absolute top-4 right-4 bg-white rounded-full p-2 shadow-md hover:bg-gray-100"
                >
                  <X size={20} className="text-gray-600" />
                </button>
              </div>
              <div className="p-8">
                <h2 className="text-3xl font-bold text-blue-800 mb-4">{selectedProperty.title}</h2>
                <div className="flex items-center text-gray-600 text-base mb-4">
                  <MapPin size={18} className="mr-2" /> {selectedProperty.location}
                </div>
                <div className="grid grid-cols-2 gap-4 mb-6 text-sm">
                  <div>
                    <p><strong>Rent:</strong> ₹{selectedProperty.price}/month</p>
                    <p><strong>Deposit:</strong> ₹{selectedProperty.deposit}</p>
                  </div>
                  <div>
                    <p><strong>Type:</strong> {selectedProperty.type}</p>
                    <p><strong>Rating:</strong> {selectedProperty.rating} / 5</p>
                  </div>
                </div>
                <div className="flex items-center gap-4 mb-6 text-sm">
                  {selectedProperty.aiVerified && (
                    <span className="text-green-600 flex items-center gap-1">
                      <CheckCircle size={18} /> AI Verified
                    </span>
                  )}
                  {selectedProperty.blockchainVerified ? (
                    <span className="text-blue-600 flex items-center gap-1">
                      <Lock size={18} /> Blockchain Verified
                    </span>
                  ) : (
                    <span className="text-yellow-600 flex items-center gap-1">
                      <Lock size={18} /> Pending Verification
                    </span>
                  )}
                </div>
                <button
                  className="w-full bg-blue-700 text-white py-3 rounded-lg hover:bg-blue-800 transition duration-300 font-semibold"
                  onClick={() => navigate('/uploadImage')} // Replace with actual application logic
                >
                  Apply Now
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  ) : (
    <AuthForm />
  );
};

export default Properties;